callGraph.callee:
sendNotification({
    kind: "registration_confirmation",
    recipient: { email: reg.volunteer.email, name: reg.volunteer.firstName },
    data: {
      volunteerName: reg.volunteer.firstName,
      eventTitle: reg.event.title,
      shifts: [{
        label: reg.shift.label,
        date: reg.shift.date.toLocaleDateString("fr-FR"),
        startTime: reg.shift.startTime,
        endTime: reg.shift.endTime,
      }],
      editToken: reg.editToken,
      orgSlug,
    },
  }).catch

d.shifts.map((s) => {
        const name = s.label && s.label !== s.roleName
          ? `${escapeHtml(s.roleName)} — ${escapeHtml(s.label)}`
          : escapeHtml(s.roleName)
        return `<li><strong>${name}</strong> · ${escapeHtml(s.date)} · ${escapeHtml(s.startTime)}–${escapeHtml(s.endTime)}</li>`
      }).join
